    override fun openDelinquencyEpisodeCandidates(): List<MemberRow> =
        backend.fetchCandidates("Member", questions.openDelinquencyEpisodeCandidates.instantiate(listOf()))
            .map { it.toMemberRow() }

    override fun openAccountReviewCandidates(): List<MemberRow> =
        backend.fetchCandidates("Member", questions.openAccountReviewCandidates.instantiate(listOf()))
            .map { it.toMemberRow() }

    override fun escalateUrgentCandidates(dueBefore: LocalDate, raisedOnAfter: LocalDate): List<TicketRow> =
        backend.fetchCandidates("Ticket", questions.escalateUrgentCandidates.instantiate(listOf(QConst.QDate(dueBefore), QConst.QDate(raisedOnAfter))))
            .map { it.toTicketRow() }

    override fun never2Candidates(): List<VisitRow> =
        backend.fetchCandidates("Visit", questions.never2Candidates.instantiate(listOf()))
            .map { it.toVisitRow() }

    override fun never3Candidates(): List<DepositRow> =
        backend.fetchCandidates("Deposit", questions.never3Candidates.instantiate(listOf()))
            .map { it.toDepositRow() }

    override fun never4Candidates(): List<TicketRow> =
        backend.fetchCandidates("Ticket", questions.never4Candidates.instantiate(listOf()))
            .map { it.toTicketRow() }

    override fun closedTicketCapture(instance: Ref.Persisted): ClosedTicketCapture? =
        backend.fetchCaptures(instance, "ClosedTicket")?.toClosedTicketCapture()
}

/** The bridge the runtime speaks through: generic protocol in, typed store out. */
class MembershipStoreResolver(
    private val store: MembershipStore,
    model: Model,
) : StateResolver {
    private val questions = MembershipStoreQuestions(model)

    override fun fetchByKey(shape: String, key: StoreKey): Row? = when (shape) {
        "Plan" -> store.plan(key)?.toRow()
        "Member" -> store.member(key)?.toRow()
        "WelcomeNote" -> store.welcomeNote(key)?.toRow()
        "EmailChange" -> store.emailChange(key)?.toRow()
        "Visit" -> store.visit(key)?.toRow()
        "AnalyticsPing" -> store.analyticsPing(key)?.toRow()
        "Deposit" -> store.deposit(key)?.toRow()
        "Charge" -> store.charge(key)?.toRow()
        "ChargeApplication" -> store.chargeApplication(key)?.toRow()
        "DelinquencyFlag" -> store.delinquencyFlag(key)?.toRow()
        "DelinquencyResolution" -> store.delinquencyResolution(key)?.toRow()
        "AuditEntry" -> store.auditEntry(key)?.toRow()
        "AccountReview" -> store.accountReview(key)?.toRow()
        "Agent" -> store.agent(key)?.toRow()
        "Ticket" -> store.ticket(key)?.toRow()
        "CloseTicket" -> store.closeTicket(key)?.toRow()
        "ReopenTicket" -> store.reopenTicket(key)?.toRow()
        "ReopenNotice" -> store.reopenNotice(key)?.toRow()
        "Escalation" -> store.escalation(key)?.toRow()
        else -> null
    }

    override fun fetchAll(shape: String): List<Row> = when (shape) {
        "Plan" -> store.allPlans().map { it.toRow() }
        "Member" -> store.allMembers().map { it.toRow() }
        "WelcomeNote" -> store.allWelcomeNotes().map { it.toRow() }
        "EmailChange" -> store.allEmailChanges().map { it.toRow() }
        "Visit" -> store.allVisits().map { it.toRow() }
        "AnalyticsPing" -> store.allAnalyticsPings().map { it.toRow() }
        "Deposit" -> store.allDeposits().map { it.toRow() }
        "Charge" -> store.allCharges().map { it.toRow() }
        "ChargeApplication" -> store.allChargeApplications().map { it.toRow() }
        "DelinquencyFlag" -> store.allDelinquencyFlags().map { it.toRow() }
        "DelinquencyResolution" -> store.allDelinquencyResolutions().map { it.toRow() }
        "AuditEntry" -> store.allAuditEntrys().map { it.toRow() }
        "AccountReview" -> store.allAccountReviews().map { it.toRow() }
        "Agent" -> store.allAgents().map { it.toRow() }
        "Ticket" -> store.allTickets().map { it.toRow() }
        "CloseTicket" -> store.allCloseTickets().map { it.toRow() }
        "ReopenTicket" -> store.allReopenTickets().map { it.toRow() }
        "ReopenNotice" -> store.allReopenNotices().map { it.toRow() }
        "Escalation" -> store.allEscalations().map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchReferencing(shape: String, field: String, target: Ref.Persisted): List<Row> = when {
        shape == "Member" && field == "plan" -> store.membersByPlan(target).map { it.toRow() }
        shape == "Member" && field == "referredBy" -> store.membersByReferredBy(target).map { it.toRow() }
        shape == "WelcomeNote" && field == "member" -> store.welcomeNotesByMember(target).map { it.toRow() }
        shape == "EmailChange" && field == "member" -> store.emailChangesByMember(target).map { it.toRow() }
        shape == "Visit" && field == "member" -> store.visitsByMember(target).map { it.toRow() }
        shape == "AnalyticsPing" && field == "visit" -> store.analyticsPingsByVisit(target).map { it.toRow() }
        shape == "Deposit" && field == "member" -> store.depositsByMember(target).map { it.toRow() }
        shape == "Charge" && field == "member" -> store.chargesByMember(target).map { it.toRow() }
        shape == "ChargeApplication" && field == "charge" -> store.chargeApplicationsByCharge(target).map { it.toRow() }
        shape == "DelinquencyFlag" && field == "member" -> store.delinquencyFlagsByMember(target).map { it.toRow() }
        shape == "DelinquencyResolution" && field == "flag" -> store.delinquencyResolutionsByFlag(target).map { it.toRow() }
        shape == "AuditEntry" && field == "member" -> store.auditEntrysByMember(target).map { it.toRow() }
        shape == "AccountReview" && field == "member" -> store.accountReviewsByMember(target).map { it.toRow() }
        shape == "Ticket" && field == "member" -> store.ticketsByMember(target).map { it.toRow() }
        shape == "Ticket" && field == "assignee" -> store.ticketsByAssignee(target).map { it.toRow() }
        shape == "CloseTicket" && field == "ticket" -> store.closeTicketsByTicket(target).map { it.toRow() }
        shape == "CloseTicket" && field == "closedBy" -> store.closeTicketsByClosedBy(target).map { it.toRow() }
        shape == "ReopenTicket" && field == "ticket" -> store.reopenTicketsByTicket(target).map { it.toRow() }
        shape == "ReopenNotice" && field == "ticket" -> store.reopenNoticesByTicket(target).map { it.toRow() }
        shape == "ReopenNotice" && field == "reassignTo" -> store.reopenNoticesByReassignTo(target).map { it.toRow() }
        shape == "Escalation" && field == "ticket" -> store.escalationsByTicket(target).map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchCandidates(shape: String, filter: QF): List<Row> {
        if (shape == "Deposit")
            questions.unappliedDepositCandidates.match(filter)?.let { h -> return store.unappliedDepositCandidates().map { it.toRow() } }
        if (shape == "Member")
            questions.activeMemberCandidates.match(filter)?.let { h -> return store.activeMemberCandidates().map { it.toRow() } }
        if (shape == "Charge")
            questions.unappliedChargeCandidates.match(filter)?.let { h -> return store.unappliedChargeCandidates().map { it.toRow() } }
        if (shape == "Member")
            questions.delinquentCandidates.match(filter)?.let { h -> return store.delinquentCandidates().map { it.toRow() } }
        if (shape == "Member")
            questions.deepDelinquentCandidates.match(filter)?.let { h -> return store.deepDelinquentCandidates().map { it.toRow() } }
        if (shape == "DelinquencyFlag")
            questions.openDelinquencyFlagCandidates.match(filter)?.let { h -> return store.openDelinquencyFlagCandidates().map { it.toRow() } }
        if (shape == "Ticket")
            questions.closedTicketCandidates.match(filter)?.let { h -> return store.closedTicketCandidates().map { it.toRow() } }
        if (shape == "Ticket")
            questions.openTicketCandidates.match(filter)?.let { h -> return store.openTicketCandidates().map { it.toRow() } }
        if (shape == "Ticket")
            questions.overdueTicketCandidates.match(filter)?.let { h -> return store.overdueTicketCandidates(h.date(0)).map { it.toRow() } }
        if (shape == "Ticket")
            questions.highPriorityCandidates.match(filter)?.let { h -> return store.highPriorityCandidates().map { it.toRow() } }
        if (shape == "Ticket")
            questions.needsAttentionCandidates.match(filter)?.let { h -> return store.needsAttentionCandidates(h.date(0)).map { it.toRow() } }
        if (shape == "Member")
            questions.renewMembershipCandidates.match(filter)?.let { h -> return store.renewMembershipCandidates(h.date(0)).map { it.toRow() } }
        if (shape == "Member")
            questions.suspendDelinquentsCandidates.match(filter)?.let { h -> return store.suspendDelinquentsCandidates().map { it.toRow() } }
        if (shape == "Member")
            questions.restoreServiceCandidates.match(filter)?.let { h -> return store.restoreServiceCandidates().map { it.toRow() } }
        if (shape == "Member")
            questions.openDelinquencyEpisodeCandidates.match(filter)?.let { h -> return store.openDelinquencyEpisodeCandidates().map { it.toRow() } }
        if (shape == "Member")
            questions.openAccountReviewCandidates.match(filter)?.let { h -> return store.openAccountReviewCandidates().map { it.toRow() } }
        if (shape == "Ticket")
            questions.escalateUrgentCandidates.match(filter)?.let { h -> return store.escalateUrgentCandidates(h.date(0), h.date(1)).map { it.toRow() } }
        if (shape == "Visit")
            questions.never2Candidates.match(filter)?.let { h -> return store.never2Candidates().map { it.toRow() } }
        if (shape == "Deposit")
            questions.never3Candidates.match(filter)?.let { h -> return store.never3Candidates().map { it.toRow() } }
        if (shape == "Ticket")
            questions.never4Candidates.match(filter)?.let { h -> return store.never4Candidates().map { it.toRow() } }
        return fetchAll(shape) // unrecognized filters fall back to the scan floor
    }

    override fun fetchCaptures(instance: Ref.Persisted, refinement: String): Map<String, Any?>? = when (refinement) {
        "ClosedTicket" -> store.closedTicketCapture(instance)?.toValues()
        else -> null
    }
}

private fun List<QConst>.date(i: Int): LocalDate = (this[i] as QConst.QDate).v
private fun List<QConst>.instant(i: Int): Instant = (this[i] as QConst.QDateTime).v

// ── row mappers: the generic wire format <-> the typed rows ──

fun Row.toPlanRow(): PlanRow = PlanRow(
    key = key,
    name = fields["name"] as String,
    price = fields["price"] as BigDecimal,
)

fun PlanRow.toRow(): Row = Row("Plan", key, buildMap {
    put("name", name)
    put("price", price)
})

fun Row.toMemberRow(): MemberRow = MemberRow(
    key = key,
    name = fields["name"] as String,
    signupEmail = fields["signupEmail"] as String,
    plan = fields["plan"] as Ref.Persisted,
    referredBy = fields["referredBy"] as Ref.Persisted?,
    joinedOn = fields["joinedOn"] as Instant,
    lastChangedOn = fields["lastChangedOn"] as Instant,
    balance = fields["balance"] as BigDecimal,
    lowestBalance = fields["lowestBalance"] as BigDecimal,
    visitCount = (fields["visitCount"] as Number).toLong(),
    suspended = fields["suspended"] as Boolean,
    engagementScore = (fields["engagementScore"] as Number).toDouble(),
)

fun MemberRow.toRow(): Row = Row("Member", key, buildMap {
    put("name", name)
    put("signupEmail", signupEmail)
    put("plan", plan)
    referredBy?.let { put("referredBy", it) }
    put("joinedOn", joinedOn)
    put("lastChangedOn", lastChangedOn)
    put("balance", balance)
    put("lowestBalance", lowestBalance)
    put("visitCount", visitCount)
    put("suspended", suspended)
    put("engagementScore", engagementScore)
})

